// Precedence: Multiplication > Addition
int x = 10, y = 2, z = 3;
int r1 = x + y * z;  // r1 == 16

// Forced Precedence (Grouping)
int r2 = (x + y) * z; // r2 == 36

// Associativity: Right-to-Left (Assignment)
int a, b, c;
a = b = c = 42; // c=42, then b=c, then a=b

// Common Pitfall: Comparison (==) > Bitwise (&)
#define MASK 0x01
int flags = 3;

// WARNING: Evaluates (MASK == 0) first.
if (flags & MASK == 0) {}

// Correct Grouping
if ((flags & MASK) == 0) {}
